import{_ as o,a as r,b as a,c as d,d as e,e as s}from"./chunks/export-result.5jQ5khUK.js";import{_ as n,o as i,c as l,a2 as g}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"エクスポート","description":"エクスポートは、コマとノートの集まりを持ち運べる形に変えます。学習用の HTML ドキュメント、スライド用の PNG、Word 派のための .docx、そして PDF 派のための印刷ビューです。","frontmatter":{"description":"エクスポートは、コマとノートの集まりを持ち運べる形に変えます。学習用の HTML ドキュメント、スライド用の PNG、Word 派のための .docx、そして PDF 派のための印刷ビューです。"},"headers":[],"relativePath":"ja/guide/export.md","filePath":"ja/guide/export.md","lastUpdated":1794883223000}'),h={name:"ja/guide/export.md"};function c(p,t,b,u,P,f){return i(),l("div",null,[...t[0]||(t[0]=[g('<h1 id="エクスポート" tabindex="-1">エクスポート <a class="header-anchor" href="#エクスポート" aria-label="Permalink to &quot;エクスポート&quot;">​</a></h1><p>エクスポートは、コマとノートの集まりを持ち運べる形に変えます。学習用の HTML ドキュメント、スライド用の PNG、Word 派のための <code>.docx</code>、そして PDF 派のための印刷ビューです。</p><figure class="shot"><img src="'+o+'" alt="レイアウトテンプレート、範囲、言語、画像の扱い、ライブプレビューを備えたエクスポートダイアログ"><figcaption>エクスポートダイアログ。左の列でドキュメントを設定し、右側でレイアウトをプレビューします。区切り線をドラッグすると幅を変更できます。</figcaption></figure><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>ノートはアプリの中に、コマにがっちり紐付いて存在します。タブレットで見直したり、印刷したり、比較をスライドに貼ったりするには、ページ画像と対応するノートを一緒に保った可搬な成果物が必要です。しかも、何もアップロードせずに。</p><h2 id="ダイアログを開く" tabindex="-1">ダイアログを開く <a class="header-anchor" href="#ダイアログを開く" aria-label="Permalink to &quot;ダイアログを開く&quot;">​</a></h2><p><code>E</code> を押すか、上部バーの <strong>エクスポート</strong> をクリックします。ダイアログは常に、表示中のページまたは話をエクスポートします。</p><h2 id="html-エクスポート" tabindex="-1">HTML エクスポート <a class="header-anchor" href="#html-エクスポート" aria-label="Permalink to &quot;HTML エクスポート&quot;">​</a></h2><h3 id="タイトルと範囲" tabindex="-1">タイトルと範囲 <a class="header-anchor" href="#タイトルと範囲" aria-label="Permalink to &quot;タイトルと範囲&quot;">​</a></h3><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th></tr></thead><tbody><tr><td><strong>タイトル</strong></td><td>ドキュメントのタイトル。推奨ファイル名にも使われます。</td></tr><tr><td><strong>現在のページ</strong></td><td>開いているページだけをエクスポートします。</td></tr><tr><td><strong>話全体（n ページ）</strong></td><td>話の中で注釈のあるすべてのページをエクスポートします。</td></tr><tr><td><strong>ノートのあるページだけ</strong></td><td>ノートのないページを飛ばします。学習ノートのまとめに便利です。</td></tr><tr><td><strong>言語</strong></td><td>ドキュメントに表示する言語。</td></tr></tbody></table><h3 id="画像の扱い" tabindex="-1">画像の扱い <a class="header-anchor" href="#画像の扱い" aria-label="Permalink to &quot;画像の扱い&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モード</th><th>動作</th></tr></thead><tbody><tr><td><strong>同名の <code>.files</code> フォルダ</strong>（既定）</td><td>HTML は隣のフォルダの画像を参照します。軽く、読み込みも速くなります。両方を一緒にコピーしてください。</td></tr><tr><td><strong>単一ファイルにまとめる</strong></td><td>画像を data URL として埋め込みます。共有するファイルは1つですが、話全体では数十 MB になることがあります。</td></tr></tbody></table><p><strong>原画にコマ枠を描く</strong> は、エクスポートする原画にコマの矩形を重ねます。これは注釈とは独立しています。</p><p><strong>これらのタグを含む注釈だけ書き出す</strong> はタグでノートを絞り込み、<strong>絞り込みを解除</strong> は選択を解除します。</p><h3 id="レイアウト" tabindex="-1">レイアウト <a class="header-anchor" href="#レイアウト" aria-label="Permalink to &quot;レイアウト&quot;">​</a></h3><p>組み込みのレイアウトテンプレートは3つあります。</p><table tabindex="0"><thead><tr><th>テンプレート</th><th>結果</th></tr></thead><tbody><tr><td><strong>左画像・右注釈</strong></td><td>左に漫画ページ、右にページとコマのノート。</td></tr><tr><td><strong>上画像・下注釈</strong></td><td>画像が全幅に広がり、ノートが下に展開されます。</td></tr><tr><td><strong>コマ比較</strong></td><td>各コマに複数言語を並べ、そのノートを添えます。</td></tr></tbody></table><p>レイアウトテンプレートは任意の名前で保存し、JSON としてエクスポートし、再びインポートできます。<code>data/templates/export.json</code> に保存されます。レイアウトのコントロールは次のとおりです。</p><table tabindex="0"><thead><tr><th>コントロール</th><th>効果</th></tr></thead><tbody><tr><td><strong>画像列の幅</strong></td><td>画像列の幅（パーセント）。</td></tr><tr><td><strong>列の間隔</strong></td><td>画像とノートの間隔。</td></tr><tr><td><strong>文字サイズ</strong></td><td>ドキュメントの基本フォント倍率。</td></tr><tr><td><strong>1行あたりの列数</strong></td><td>1行に並べるページブロックの数。</td></tr></tbody></table><p>レイアウトは自動で記憶されます。ライブプレビューの区切り線をドラッグして画像幅を設定することもできます。</p><figure class="shot"><img src="'+r+'" alt="エクスポートダイアログのテンプレート操作。名前を付けて現在のレイアウトを保存、JSON のインポート、保存済みテンプレートの適用 / 書き出し / 削除"><figcaption>テンプレート操作。名前を付けて現在のレイアウトを保存し、JSON をインポートできます。保存済みテンプレートは適用・書き出し・削除ができます。</figcaption></figure><h3 id="生成" tabindex="-1">生成 <a class="header-anchor" href="#生成" aria-label="Permalink to &quot;生成&quot;">​</a></h3><ol><li>範囲、言語、画像の扱い、レイアウトを選びます。</li><li><strong>HTML を生成</strong> をクリックします。</li><li>完了すると、エクスポートしたページ数とファイルの場所が表示されます。</li><li><strong>HTML を開く</strong> でブラウザで開くか、<strong>HTML をダウンロード</strong> でコピーを保存します。既定の画像モードでは、<code>.files</code> フォルダも一緒にコピーしてください。</li></ol><p>ファイルはプロジェクトの <code>exports/</code> フォルダに書き出されます。HTML はディスクから直接開けます。</p><h3 id="印刷" tabindex="-1">印刷 <a class="header-anchor" href="#印刷" aria-label="Permalink to &quot;印刷&quot;">​</a></h3><p>生成された HTML には印刷用スタイルが含まれます。背景は削除され、ページ幅は制限されず、ページブロックは画像の途中で分割されません。ブラウザでファイルを開き、通常の <strong>印刷</strong> コマンドで、ブラウザの印刷ダイアログから PDF を作成してください。</p><div class="tip custom-block"><p class="custom-block-title">PDF への印刷</p><p>エクスポートダイアログで <strong>PDF（印刷）</strong> を選ぶと、印刷ページがブラウザの印刷ダイアログと一緒に開きます。そこで <strong>PDF に保存</strong> を選んでください。<a href="#pdf-と-word">PDF と Word</a> を参照してください。</p></div><h2 id="png-エクスポート" tabindex="-1">PNG エクスポート <a class="header-anchor" href="#png-エクスポート" aria-label="Permalink to &quot;PNG エクスポート&quot;">​</a></h2><p><strong>PNG を書き出し</strong> セクションは、ドキュメントを介さずに画像を生成します。</p><table tabindex="0"><thead><tr><th>モード</th><th>内容</th></tr></thead><tbody><tr><td><strong>ページ全体</strong></td><td>コマ枠と注釈を付けたページ画像。</td></tr><tr><td><strong>現在のコマ</strong></td><td>選択したコマを切り取り、位置合わせした画像。</td></tr><tr><td><strong>3言語コラージュ</strong></td><td>同じコマ（コマを選択していない場合はページ全体）について、選択した言語を並べた画像。</td></tr></tbody></table><p>オプション:</p><ul><li><strong>注釈を含める（n）</strong> — 注釈レイヤーを PNG に描画します。件数は含まれるマークの数を示します。</li><li><strong>出力サイズ</strong> — 既定では元のピクセルを維持します。小红书 3:4（1080×1440）、1:1、4:3、長図（幅 1080）、Instagram 4:5 と 9:16、Pinterest 2:3、縦読み幅 800、B5 / A4 / A5 の 300 dpi 印刷サイズも選べます。画像は比率を保って余白付きで収め、トリミングはしません。選択は次回も保持されます。</li><li>ページ全体と現在のコマの PNG は <strong>優先言語（下地画像）</strong> を使い、コラージュは選択した比較言語を使います。</li><li><strong>現在のコマ</strong> は、ワークベンチでコマを選択するまで無効です。</li></ul><p>PNG はブラウザで生成され、ブラウザのダウンロードフォルダに保存されます。スライド、文書、チャットにそのまま貼れます。</p><figure class="shot"><img src="'+a+'" alt="エクスポートダイアログ。範囲、言語チップ、画像の扱い、PNG モード、レイアウトのスライダー"><figcaption>エクスポートダイアログで PNG モードを選んだ状態。ページ全体と現在のコマは優先言語（下地画像）、3 言語コラージュは選択した比較言語を使います。</figcaption></figure><figure class="shot"><img src="'+d+'" alt="同じページから書き出した 3 種類の PNG。ページ全体、現在のコマ、3 言語コラージュと各サイズ"><figcaption>同じページから書き出した 3 種類の PNG。ページ全体、現在のコマ、3 言語コラージュ（この図では注釈を含めていません）。</figcaption></figure><h2 id="共有画像" tabindex="-1">共有画像 <a class="header-anchor" href="#共有画像" aria-label="Permalink to &quot;共有画像&quot;">​</a></h2><p>エクスポートダイアログの <strong>共有画像</strong> セクションは、そのまま投稿できる比率で画像を書き出します。仕上げにもう一度画像編集ソフトを開く必要はありません。</p><table tabindex="0"><thead><tr><th>プリセット</th><th>出力</th></tr></thead><tbody><tr><td><strong>カバー · 1080×1440 JPEG</strong></td><td>通常のフィード用カバー、JPEG 品質 88。</td></tr><tr><td><strong>高画質カバー · 1242×1656 JPEG</strong></td><td>少し大きいカバー、JPEG 品質 90。</td></tr><tr><td><strong>単一コマ · 1080×1440 JPEG</strong></td><td>読み順にコマごとに1枚、品質 85。</td></tr><tr><td><strong>3言語比較 · 1080×1440 PNG</strong></td><td>有効な全言語を並べて1枚の PNG に。</td></tr><tr><td><strong>長いページ · 最大 1080×3240 JPEG</strong></td><td>長いページは帯に分割。上部 1080×1440 はカバーとしても保存されます。</td></tr></tbody></table><ul><li><strong>範囲</strong> はダイアログに従い、現在のページまたは話全体です。進捗は <code>n / 全ページ</code> で表示し、飛ばしたページは理由（選択言語に画像がない、コマが検出されていない）とともに一覧に出ます。黙って失敗することはありません。</li><li><strong>言語</strong> は単一コマとカバーの絵を選びます。3言語比較プリセットは有効な全言語を使います。</li><li><strong>ページ / 言語バーを追加</strong> は下部のセーフエリア内に小さなラベルを描きます。端には置かないため、プラットフォームが切り取っても読めます。</li><li><strong>注釈を焼き込む</strong> は、アンカーと引き出し線を含む注釈レイヤーを合成してから描画します。きれいな絵が欲しいときはオフにします。</li><li>ファイルはデスクトップ版では <code>exports/&lt;バッチ&gt;/</code> に、Web 版ではブラウザーのダウンロード先に保存されます。1バッチが 18 枚を超える場合や、1枚が 20 MB に近づく場合に警告が出ます。</li></ul><figure class="shot"><img src="'+e+'" alt="エクスポートダイアログの共有画像セクション。カバー、高画質カバー、単一コマ、3言語比較、長いページのプリセット"><figcaption>共有画像。ダイアログからプラットフォーム別のプリセットをそのまま書き出せます。1080×1440 のカバー、読み順に1コマずつ、3言語比較、帯に分割した長いページ。ページ / 言語バーの追加と注釈の焼き込みにも対応します。</figcaption></figure><h2 id="pdf-と-word" tabindex="-1">PDF と Word <a class="header-anchor" href="#pdf-と-word" aria-label="Permalink to &quot;PDF と Word&quot;">​</a></h2><p>エクスポートダイアログの出力形式は <strong>HTML</strong>、<strong>Word 文書</strong>、<strong>PDF（印刷）</strong> の3つです。</p><h3 id="word-docx" tabindex="-1">Word（<code>.docx</code>） <a class="header-anchor" href="#word-docx" aria-label="Permalink to &quot;Word（`.docx`）&quot;">​</a></h3><ol><li><code>E</code> を押し、<strong>Word 文書</strong> を選びます。</li><li>範囲、言語、ノートのタグ絞り込みをいつもどおり設定します。</li><li><strong>Word を生成</strong> をクリックし、<strong>​.docx をダウンロード</strong> を押します。</li></ol><p>文書にはページ画像が残り、ページノートとコマノートは編集可能な Word テキストになります。既定では<strong>注釈をページ画像に焼き込みます</strong>: ブラウザーが各ページの PNG にベクター注釈を合成してから生成するため、<code>.docx</code> には注釈付きの画面が入ります。合成画像が届かなかった場合（書き出しの中断、または選択した言語にそのページの画像が無い場合）は、そのページだけ元の画像に戻り、結果に <code>WARN_EXPORT_ANNOTATIONS_UNBAKED</code> の警告が付きます。<strong>注釈を含める</strong> を外せば、常に元のページ画像を書き出します。</p><h3 id="pdf-印刷" tabindex="-1">PDF（印刷） <a class="header-anchor" href="#pdf-印刷" aria-label="Permalink to &quot;PDF（印刷）&quot;">​</a></h3><ol><li><strong>PDF（印刷）</strong> を選び、<strong>印刷ページを生成</strong> をクリックします。</li><li>印刷ページが新しいタブで開き、ブラウザの印刷ダイアログも立ち上がります。</li><li>印刷ダイアログで <strong>PDF に保存</strong> を選びます。</li></ol><p>画像は1ページに収まるよう調整され、ノートはページに付随します。背景は削除され、ページ幅の制限は解除され、画像の途中での改ページも避けられます。</p><h3 id="プレーンテキスト-markdown" tabindex="-1">プレーンテキスト / Markdown <a class="header-anchor" href="#プレーンテキスト-markdown" aria-label="Permalink to &quot;プレーンテキスト / Markdown&quot;">​</a></h3><p><strong>ページのコンテキストをコピー</strong>、またはノートの<strong>描画 / ソース</strong>切り替えを使います。本文は Markdown です。</p><h2 id="エクスポートテンプレート" tabindex="-1">エクスポートテンプレート <a class="header-anchor" href="#エクスポートテンプレート" aria-label="Permalink to &quot;エクスポートテンプレート&quot;">​</a></h2><p>エクスポートテンプレート（<code>.mnexp</code>）はレイアウトとスタイルの設定を保存し、同じ見た目を再利用・共有できるようにします。テンプレートのエクスポートとインポートは、サイドバーの <strong>交換ファイル…</strong> から行います。インポートしたテンプレートは検証され、元のファイルは <code>data/backups/exchange/</code> にバックアップされます。</p><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>HTML の画像が壊れている。</strong> 既定のモードでは、<code>.files</code> フォルダも HTML と一緒に移動する必要があります。</li><li><strong>単一ファイルのエクスポートが巨大になる。</strong> 想定どおりです。すべての画像が埋め込まれます。話全体には <code>.files</code> モードを使ってください。</li><li><strong>エクスポートにページが出てこない。</strong> ノートがなく <strong>ノートのあるページだけ</strong> がオンになっているか、選択した言語の画像がないページです。</li><li><strong>PNG にコマ枠がない。</strong> PNG エクスポートは注釈の切り替えを使います。<strong>注釈を含める</strong> を有効にしてください。コマ枠は注釈ではなくコマの矩形から描かれる点に注意してください。</li><li><strong>印刷結果が切れる。</strong> ブラウザの印刷倍率を「ページに合わせる」にし、網掛けが必要な場合だけ背景のグラフィックを有効にしてください。</li><li><strong>Word でレイアウトが崩れる。</strong> Markdown のソースではなく、描画済みの HTML を貼り付けてください。Word は HTML の表や画像を保てますが、2 カラムのドラッグ幅は保てません。</li><li><strong>.docx / PDF のボタンがない。</strong> どちらもエクスポートダイアログにあります。まず <strong>Word 文書</strong> か <strong>PDF（印刷）</strong> を選んでください。Word は既定で注釈を画像に焼き込みます。<code>WARN_EXPORT_ANNOTATIONS_UNBAKED</code> の警告だけが出た場合は、そのページの合成画像が届いていないので再生成してください。</li><li><strong>出力フォルダに書き込めない。</strong> パッケージ化したデスクトップ版では、<code>exports/</code> は選択したライブラリフォルダの中にあります。</li></ul><figure class="shot"><img src="'+s+'" alt="ブラウザで開いた書き出し HTML。左に漫画ページ、右にページとコマのノート"><figcaption>ブラウザで開いた書き出し HTML。左に漫画ページ、右にページとコマのノート。</figcaption></figure><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/notes">ノート</a> — ドキュメントに入る内容。</li><li><a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> — 開いた <code>.mnproj</code> へ書き戻す場合や、コピーとして保存する場合。</li><li><a href="/KomaYomi-docs/ja/guide/shortcuts">キーボードショートカット</a> — <code>E</code> でこのダイアログが開きます。</li></ul>',57)])])}const q=n(h,[["render",c]]);export{_ as __pageData,q as default};
